_EXPECTED = {code for code, _ in LANGUAGE_OPTIONS if code != "en"}
if set(REMAINING_LEDGER_ROWS) != _EXPECTED:
    raise ValueError("Remaining ledger locale coverage is incomplete")
REMAINING_LEDGER_CATALOGS: dict[str, dict[str, str]] = {
    code: dict(zip(REMAINING_LEDGER_KEYS, row.split("|"), strict=True))
    for code, row in REMAINING_LEDGER_ROWS.items()
}
_formatter = Formatter()
for _code, _entries in REMAINING_LEDGER_CATALOGS.items():
    for _source, _value in _entries.items():
        if not _value.strip() or _value.casefold() == _source.casefold():
            raise ValueError(
                f"Missing native remaining ledger: {_code}: {_source}"
            )
        if Counter(
            slot for _, slot, _, _ in _formatter.parse(_source) if slot
        ) != Counter(
            slot for _, slot, _, _ in _formatter.parse(_value) if slot
        ):
            raise ValueError(
                f"Remaining ledger slot mismatch: {_code}: {_source}"
            )
